def find_first_occurrence(arr: list[int], target: int) -> int:
    # BUGGY IMPLEMENTATION:
    low = 0
    high = len(arr)
    ans = -1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid  # BUG: Returns any occurrence, not first!
        elif arr[mid] < target:
            low = mid
        else:
            high = mid
    return ans

