import unittest
from solution import find_first_occurrence

class TestBinarySearch(unittest.TestCase):
    def test_first_occurrence_with_duplicates(self):
        arr = [1, 2, 2, 2, 3, 4, 5]
        self.assertEqual(find_first_occurrence(arr, 2), 1)

    def test_all_duplicates(self):
        arr = [7, 7, 7, 7, 7]
        self.assertEqual(find_first_occurrence(arr, 7), 0)

    def test_not_found(self):
        arr = [1, 3, 5, 7]
        self.assertEqual(find_first_occurrence(arr, 4), -1)
        self.assertEqual(find_first_occurrence([], 10), -1)

    def test_extremes(self):
        arr = [2, 4, 6, 8, 10]
        self.assertEqual(find_first_occurrence(arr, 2), 0)
        self.assertEqual(find_first_occurrence(arr, 10), 4)

if __name__ == '__main__':
    unittest.main()
